<?php
require __DIR__.'/bootstrap.php';
// Backups stay outside the document root. Protect/copy them to separate storage.
$directory=Yii::app()->basePath.'/runtime/backups/'.date('Ymd-His').'-'.bin2hex(random_bytes(3));if(!mkdir($directory,0700,true))throw new Exception('Cannot create backup directory');$db=Yii::app()->db;$tx=$db->beginTransaction();
try{$dump=array('format'=>1,'created_at'=>date(DATE_ATOM),'driver'=>$db->driverName,'tables'=>array());foreach($db->schema->getTableNames() as $table){$dump['tables'][$table]=array('rows'=>$db->createCommand()->select('*')->from($table)->queryAll());}$json=json_encode($dump,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);if(file_put_contents($directory.'/database.json',$json)===false)throw new Exception('Cannot save backup');$tx->commit();}catch(Exception $e){if($tx->active)$tx->rollback();throw $e;}
$source=realpath(Yii::app()->params['uploadsDir']);$iterator=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($source,FilesystemIterator::SKIP_DOTS));foreach($iterator as $file){if($file->isLink()||!$file->isFile())continue;$relative=substr($file->getPathname(),strlen($source)+1);$target=$directory.'/uploads/'.$relative;if(!is_dir(dirname($target)))mkdir(dirname($target),0700,true);if(!copy($file->getPathname(),$target))throw new Exception('Cannot copy media');}
if(is_file(Yii::app()->basePath.'/config/security.key'))copy(Yii::app()->basePath.'/config/security.key',$directory.'/security.key');file_put_contents($directory.'/SHA256',hash_file('sha256',$directory.'/database.json'));echo 'Backup created: '.$directory."\n";
